import random
import string
from typing import List

# This generator targets stubs that consume arbitrary binary from FUZZ_PARAM_STR().
# It produces varied yet valid binary buffers, sometimes prefixed with UTF BOMs,
# ensures IPv6-sized payloads when chosen, and mixes ASCII, UTF-8, and random bytes.

MAX_SIZE = 4096

UTF8_BOM = b"\xEF\xBB\xBF"
UTF16BE_BOM = b"\xFE\xFF"
UTF16LE_BOM = b"\xFF\xFE"

WORDS = [
    b"hello", b"world", b"lexbor", b"encoding", b"decode", b"encode",
    b"punycode", b"url", b"ipv6", b"params", b"normalization", b"nfc",
    b"nfd", b"nfkc", b"nfkd", b"test", b"data", b"chunk", b"buffer"
]

UTF8_SAMPLES = [
    "πλήρης".encode("utf-8"),
    "こんにちは".encode("utf-8"),
    "Здравствуй".encode("utf-8"),
    "مرحبا".encode("utf-8"),
    "😀😁😂🤣😜".encode("utf-8"),
]


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    out = bytearray()
    while len(out) < n:
        choice = rng.randint(0, 4)
        remain = n - len(out)
        if choice == 0:
            # printable ascii run
            run = min(remain, rng.randint(1, 32))
            # Build bytes from chosen printable characters
            segment = ''.join(rng.choice(string.printable) for _ in range(run)).encode('latin1', 'ignore')
            if len(segment) < run:
                # pad with spaces if encoding ignored anything
                segment = (segment + b' ' * run)[:run]
            out.extend(segment[:run])
        elif choice == 1:
            run = min(remain, rng.randint(1, 32))
            out.extend(rng.randrange(256) for _ in range(run))
        elif choice == 2:
            w = rng.choice(WORDS)
            out.extend(w[: min(len(w), remain)])
        elif choice == 3 and UTF8_SAMPLES:
            s = rng.choice(UTF8_SAMPLES)
            out.extend(s[: min(len(s), remain)])
        else:
            run = min(remain, rng.randint(1, 32))
            out.extend((ord('0') + rng.randrange(10)) for _ in range(run))
    return bytes(out[:n])


def _maybe_prefix_bom(rng: random.Random, payload: bytes) -> bytes:
    mode = rng.randint(0, 6)
    if mode == 0:
        return UTF8_BOM + payload
    if mode == 1:
        return UTF16BE_BOM + payload
    if mode == 2:
        return UTF16LE_BOM + payload
    return payload


def _make_ipv6_sized_payload(rng: random.Random) -> bytes:
    size = 16
    extra = rng.choice([0, rng.randint(1, 48), rng.randint(49, 256)])
    return _rand_bytes(rng, size + extra)


def _choose_length(rng: random.Random) -> int:
    bucket = rng.random()
    if bucket < 0.10:
        return 0
    if bucket < 0.35:
        return rng.randint(1, 32)
    if bucket < 0.55:
        return 16
    if bucket < 0.85:
        return rng.randint(33, 512)
    return rng.randint(513, MAX_SIZE)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    profile = rng.randint(0, 4)

    if profile == 0:
        length = _choose_length(rng)
        payload = _rand_bytes(rng, length)
        data = _maybe_prefix_bom(rng, payload)
    elif profile == 1:
        payload = _make_ipv6_sized_payload(rng)
        data = _maybe_prefix_bom(rng, payload)
    elif profile == 2:
        pieces: List[bytes] = []
        count = rng.randint(1, 10)
        for _ in range(count):
            k = rng.choice(WORDS).replace(b" ", b"")
            vlen = rng.randint(0, 24)
            v = _rand_bytes(rng, vlen)
            pieces.append(k + b"=" + v)
        query = b"&".join(pieces)
        candidates = [query, b"?" + query, query + b"#frag", query + b"%20"]
        data = rng.choice(candidates)[:MAX_SIZE]
    elif profile == 3:
        chunks = []
        total = rng.randint(0, 2048)
        size_acc = 0
        while size_acc < total:
            if rng.random() < 0.7:
                s = rng.choice(UTF8_SAMPLES)
            else:
                s = _rand_bytes(rng, rng.randint(1, 16))
            chunks.append(s)
            size_acc += len(s)
        data = b"".join(chunks)[:MAX_SIZE]
        if rng.random() < 0.4:
            data = UTF8_BOM + data
    else:
        length_choices = [0, 1, 2, 4, 8, 16, 32, 64, 128, 256, 512]
        if rng.random() < 0.5:
            length = rng.choice(length_choices)
        else:
            length = _choose_length(rng)
        data = _rand_bytes(rng, length)

    if len(data) > MAX_SIZE:
        data = data[:MAX_SIZE]

    return data

import random
from typing import List, Tuple

# Target data type: UTF-8 text
# This generator produces valid and interesting UTF-8 byte sequences that exercise
# normalization, quick-check, Punycode, and URL parsing/query APIs.
# Avoid non-ASCII bytes in source literals; construct them via .encode('utf-8').

ASCII: List[bytes] = [
    b"", b"a", b"hello", b"HTTP", b"user:pass", b"localhost",
    b"http://example.com/", b"https://example.com/path?x=1#frag",
    b"/?q=x&y=y", b"name=value", b"key=", b"=value", b"--",
]

# Predefined Unicode snippets (encoded at runtime)
UNICODE_SNIPPETS: List[bytes] = [
    "e\u0301".encode("utf-8"),            # e + COMBINING ACUTE ACCENT
    "\u00e9".encode("utf-8"),            # precomposed é
    "\u1100\u1161".encode("utf-8"),     # Hangul choseong + jungseong
    "\uAC00".encode("utf-8"),            # 가
    ("A" + "\u0301\u0327\u0308").encode("utf-8"),
    "münchen".encode("utf-8"),
    "παράδειγμα".encode("utf-8"),
    "例え".encode("utf-8"),
    "δοκιμή".encode("utf-8"),
    "שלום".encode("utf-8"),
    "😀😃😄".encode("utf-8"),
    ("Z" + "\u0301\u0302\u0303\u0304\u0305\u0306\u0307\u0308").encode("utf-8"),
]

# URL-focused pieces including Unicode host labels that would go via punycode
URL_PARTS: List[bytes] = [
    b"http://",
    b"https://",
    b"ws://",
    b"ftp://",
    b"file://",
    "https://münchen.de".encode("utf-8"),
    "http://παράδειγμα.δοκιμή".encode("utf-8"),
    "http://例え.テスト".encode("utf-8"),
]

QUERY_KEYS = [b"q", b"lang", b"utf8", b"id", b"name", b"empty", b"emoji"]
QUERY_VALUES: List[bytes] = [
    b"test", b"value", b"1", b"%20", "münchen".encode("utf-8"),
    "παράδειγμα".encode("utf-8"), "😀".encode("utf-8"), b"", b"x+y",
]

COMBINING_RANGE = list(range(0x0300, 0x0370))


def _rand_utf8_codepoint(r: random.Random) -> int:
    choices: List[Tuple[int, int]] = [
        (0x0020, 0x007E),   # ASCII printable
        (0x00A1, 0x024F),   # Latin-1 Supplement + Latin Extended-A/B
        (0x0370, 0x03FF),   # Greek
        (0x0400, 0x04FF),   # Cyrillic
        (0x0590, 0x05FF),   # Hebrew
        (0x0600, 0x06FF),   # Arabic
        (0x3040, 0x309F),   # Hiragana
        (0x30A0, 0x30FF),   # Katakana
        (0x4E00, 0x9FFF),   # CJK Unified Ideographs
        (0x1F600, 0x1F64F), # Emoticons
    ]
    lo, hi = choices[r.randrange(len(choices))]
    cp = r.randrange(lo, hi + 1)
    # Avoid surrogates and non-characters
    if 0xD800 <= cp <= 0xDFFF or (cp & 0xFFFE) == 0xFFFE:
        return 0x41  # 'A'
    return cp


def _encode_utf8(cp: int) -> bytes:
    return chr(cp).encode("utf-8", errors="strict")


def _random_combining_sequence(r: random.Random, base: str = "A") -> bytes:
    n = r.randint(1, 6)
    seq = [ord(base)] + [r.choice(COMBINING_RANGE) for _ in range(n)]
    return b"".join(chr(c).encode("utf-8") for c in seq)


def _make_query(r: random.Random) -> bytes:
    pairs = []
    count = r.randint(1, 6)
    for _ in range(count):
        k = r.choice(QUERY_KEYS)
        v = r.choice(QUERY_VALUES)
        pairs.append(k + b"=" + v)
    return b"?" + b"&".join(pairs)


def _make_path(r: random.Random) -> bytes:
    segs = []
    count = r.randint(0, 5)
    for _ in range(count):
        choice = r.randint(0, 3)
        if choice == 0:
            segs.append(b"a" * r.randint(1, 6))
        elif choice == 1:
            segs.append(_random_combining_sequence(r, base=chr(0x61 + r.randint(0, 25))))
        elif choice == 2:
            segs.append(_encode_utf8(_rand_utf8_codepoint(r)))
        else:
            segs.append(r.choice(UNICODE_SNIPPETS))
    return b"/" + b"/".join(segs) if segs else b"/"


def _make_unicode_label(r: random.Random) -> bytes:
    parts: List[bytes] = []
    length = r.randint(3, 10)
    for _ in range(length):
        if r.random() < 0.5:
            parts.append(_encode_utf8(_rand_utf8_codepoint(r)))
        else:
            parts.append(_random_combining_sequence(r, base=chr(0x61 + r.randint(0, 25))))
    # Ensure at least one non-ASCII
    parts.append("ä".encode("utf-8"))
    return b"".join(parts).replace(b" ", b"-")


def _make_url(r: random.Random) -> bytes:
    # Combine scheme, host (possibly Unicode), port optional, path, query, fragment
    if r.random() < 0.4:
        scheme = r.choice(URL_PARTS)
    else:
        scheme = r.choice([b"http://", b"https://", b"ftp://", b"ws://", b"file://"])
    if scheme.startswith(b"file"):
        host = b""
    elif r.random() < 0.6:
        host = _make_unicode_label(r) + b"." + _make_unicode_label(r)
    else:
        host = r.choice([b"example.com", b"localhost", b"127.0.0.1", b"[2001:db8::1]"])
    port = (b":" + str(r.randint(1, 65535)).encode("ascii")) if r.random() < 0.3 else b""
    path = _make_path(r)
    query = _make_query(r) if r.random() < 0.7 else b""
    frag_choice = r.choice(["frag", "ä", "sec1"])
    frag = (b"#" + frag_choice.encode("utf-8")) if r.random() < 0.4 else b""
    return scheme + host + port + path + query + frag


def _make_punycode_input(r: random.Random) -> bytes:
    choice = r.randint(0, 3)
    if choice == 0:
        return _make_unicode_label(r)
    elif choice == 1:
        return r.choice([s for s in UNICODE_SNIPPETS if s])
    elif choice == 2:
        return "bücher".encode("utf-8")
    else:
        return b"abc-" + _make_unicode_label(r)


def _maybe_bom_prefix(r: random.Random) -> bytes:
    pick = r.randint(0, 10)
    if pick == 0:
        return bytes([0xEF, 0xBB, 0xBF])  # UTF-8 BOM
    elif pick == 1:
        return bytes([0xFE, 0xFF])       # UTF-16BE BOM
    elif pick == 2:
        return bytes([0xFF, 0xFE])       # UTF-16LE BOM
    return b""


def _assemble_chunks(r: random.Random) -> bytes:
    chunks: List[bytes] = []
    chunks.append(_maybe_bom_prefix(r))
    chunks.append(_make_url(r))
    if r.random() < 0.7:
        chunks.append(_make_query(r)[1:])  # without leading '?'
    for _ in range(r.randint(1, 3)):
        chunks.append(_make_punycode_input(r))
    norm_bits = [
        _random_combining_sequence(r, base="A"),
        ("e\u0301 and \u00e9").encode("utf-8"),
        r.choice(UNICODE_SNIPPETS),
    ]
    chunks.extend(norm_bits)
    chunks.append(r.choice(ASCII))
    chunks.append("✓".encode("utf-8").hex().encode("ascii"))  # percent-like hex without %
    sep = r.choice([b"\n", b"\r\n", b"&", b" ", b"\t", b"\x00"])  # include NUL sometimes
    data = sep.join(chunks)
    return data[:4096]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    mode = r.randint(0, 2)
    if mode == 0:
        data = _make_url(r)
        if r.random() < 0.8:
            data += _make_query(r)
        if r.random() < 0.5:
            data = _maybe_bom_prefix(r) + data
    elif mode == 1:
        parts = []
        for _ in range(r.randint(1, 4)):
            parts.append(_make_punycode_input(r))
        data = b".".join(parts)
        if r.random() < 0.5:
            data = _maybe_bom_prefix(r) + data
    else:
        parts = []
        for _ in range(r.randint(3, 8)):
            if r.random() < 0.5:
                parts.append(_random_combining_sequence(r, base=chr(0x61 + r.randint(0,25))))
            else:
                parts.append(r.choice(UNICODE_SNIPPETS))
        data = b" ".join(parts)
        if r.random() < 0.5:
            data += b"\n" + _make_query(r)
    if r.random() < 0.4:
        data = _assemble_chunks(r)
    return bytes(data[:4096])
